from __future__ import annotations

from decimal import Decimal
from typing import Dict

from .amounts import BudgetLimit, nonnegative, parse_amount
from .errors import ValidationError


class CategoryBudgets:
    """Store and manage per-category monthly budget limits."""

    def __init__(self):
        self._limits: Dict[str, Dict[str, BudgetLimit]] = {}

    def set_limit(self, category: str, month: str, amount: str) -> None:
        """Set a budget limit for a category in a specific month.

        Args:
            category: The category name
            month: Month in YYYY-MM format
            amount: The limit amount as a string

        Raises:
            ValidationError: If amount is negative or invalid
        """
        nonnegative(parse_amount(amount))
        if month not in self._limits:
            self._limits[month] = {}
        self._limits[month][category] = BudgetLimit(category=category, limit=parse_amount(amount))

    def get_limit(self, category: str, month: str) -> Decimal | None:
        """Get the budget limit for a category in a specific month.

        Returns None if no limit is set.
        """
        if month not in self._limits:
            return None
        return self._limits[month].get(category)

    def get_all_limits(self, month: str) -> Dict[str, BudgetLimit]:
        """Get all limits for a specific month."""
        return self._limits.get(month, {})

    def has_limit(self, category: str, month: str) -> bool:
        """Check if a limit exists for a category in a month."""
        return category in self._limits.get(month, {})"}

