    """Return total, income, expenses, and category amounts with budget status.

    Args:
        rows: List of transactions
        month: Month in YYYY-MM format
        budgets: Optional CategoryBudgets instance for budget limits

    Returns:
        Dictionary with month, income, expenses, net, categories, count, and budget_status
    """
    selected = month_transactions(rows, month)
    income = add_amounts(row.amount for row in selected if row.amount > 0)
    expenses = add_amounts(row.amount for row in selected if row.amount < 0)
    categories = {}
    for row in selected:
        categories[row.category] = categories.get(row.category, Decimal("0.00")) + row.amount

    budget_status = {}
    if budgets is not None:
        for category in categories:
            actual = categories[category]
            limit = budgets.get_limit(category, month)
            budget_status[category] = {
                "actual": actual,
                "limit": limit if limit is not None else None
            }

    return {"month": month, "income": income, "expenses": expenses,
            "net": income + expenses, "categories": dict(sorted(categories.items())),
            "count": len(selected), "budget_status": budget_status}

